{"content": "import sys
from pathlib import Path

import torch
import torch.nn as nn

_KERNEL_BUILD = Path(__file__).resolve().parent / "kernel" / "build"
_LIB_PATTERN = str(_KERNEL_BUILD / "ForeachSinh_ext*")

# 优先 whl import（触发 TORCH_LIBRARY 注册）
try:
    import ForeachSinh_ext  # noqa: F401
except ImportError:
    # 兜底：直加载 .so
    if _LIB_PATTERN not in "".join(sys.path):
        import glob as _glob
        _libs = _glob.glob(_LIB_PATTERN)
        if _libs:
            torch.ops.load_library(_libs[0])


class ModelNew(nn.Module):
    def __init__(self):
        super().__init__()

    def forward(self, inputs):
        # ForeachSinh: apply sinh elementwise to each tensor in the list
        outputs = []
        for x in inputs:
            assert x.dtype in (torch.float16, torch.bfloat16, torch.float32)
            assert x.is_contiguous()
            y = torch.ops.npu.ForeachSinh(x)
            outputs.append(y)
        return outputs
