18	at::TensorList foreach_tanh(const at::TensorList &inputs)
19	{
20	    TORCH_CHECK(inputs.size() > 0, "foreach_tanh: input list must not be empty");
21	
22	    auto dtype = inputs[0].scalar_type();
23	    TORCH_CHECK(dtype == at::kHalf || dtype == at::kBFloat16 || dtype == at::kFloat,
24	                "foreach_tanh: only float16, bfloat16 and float32 are supported, got ", dtype);
25	
26	    int64_t totalLength = 0;
27	    for (const auto &t : inputs) {
28	        totalLength += t.numel();
29	    }
30	
31	    std::vector<at::Tensor> outputs;
32	    for (const auto &t : inputs) {
33	        outputs.push_back(at::empty_like(t));
34	    }
35	
36	    if (totalLength == 0) {
37	        return at::TensorList(outputs);
38	    }
39	
40	    auto flatInput = at::empty({totalLength}, inputs[0].options());
41	    auto flatOutput = at::empty({totalLength}, inputs[0].options());
42	
43	    int64_t offset = 0;
44	    for (const auto &t : inputs) {
45	        if (t.numel() > 0) {
46	            flatInput.narrow(0, offset, t.numel()).copy_(t.reshape({-1}));
47	            offset += t.numel();
48	        }
49	    }
50	
51	    int64_t dtypeSize = flatInput.element_size();
52	
53	    auto ascendc_platform = platform_ascendc::PlatformAscendCManager::GetInstance();
54	    int64_t coreNum = static_cast<int64_t>(ascendc_platform->GetCoreNumAiv());
55	    uint64_t ubSize;
56	    ascendc_platform->GetCoreMemSize(platform_ascendc::CoreMemType::UB, ubSize);
57	    int64_t ubSizeLimit = static_cast<int64_t>(ubSize);
58	
59	    int64_t totalLengthCore = (totalLength + coreNum - 1) / coreNum;
60	    int64_t totalLengthCoreAlign = (totalLengthCore + CACHE_LINE_BYTE_LENGTH - 1)
61	                                    / CACHE_LINE_BYTE_LENGTH * CACHE_LINE_BYTE_LENGTH;
62	
63	    int64_t usedCoreNum = (totalLength + totalLengthCoreAlign - 1) / totalLengthCoreAlign;
64	    int64_t formerNum = usedCoreNum - 1;
65	    int64_t formerLength = totalLengthCoreAlign;
66	    int64_t tailLength = totalLength - formerNum * formerLength;
67	
68	    int64_t bufferCoefficient = (dtypeSize == 4) ? 20 : 16;
69	    int64_t maxTileElements = ubSizeLimit / bufferCoefficient;
70	    int64_t alignElements = 32 / dtypeSize;
71	    int64_t tileLength = (maxTileElements / alignElements) * alignElements;
72	    if (tileLength == 0) {
73	        tileLength = alignElements;
74	    }
75	
76	    uint32_t blockDim = static_cast<uint32_t>(usedCoreNum);
77	
78	    int64_t formerNumLval = formerNum;
79	    int64_t formerLengthLval = formerLength;
80	    int64_t tailLengthLval = tailLength;
81	    int64_t tileLengthLval = tileLength;
82	    int64_t dtypeSizeLval = dtypeSize;
83	
84	    EXEC_KERNEL_CMD(foreach_tanh, blockDim,
85	                    flatInput, flatOutput,
86	                    formerNumLval, formerLengthLval, tailLengthLval,
87	                    tileLengthLval, dtypeSizeLval);
88	
89	    offset = 0;
90	    for (size_t i = 0; i < inputs.size(); ++i) {
91	        if (inputs[i].numel() > 0) {
92	            outputs[i].copy_(flatOutput.narrow(0, offset, inputs[i].numel()).reshape(inputs[i].sizes()));
93	            offset += inputs[i].numel();
94	        }
95	    }
96	
97	    static thread_local std::vector<at::Tensor> resultStorage;
98	    resultStorage = std::move(outputs);
99	    return at::TensorList(resultStorage);
100	}
