13	constexpr int32_t BUFFER_NUM = 2;
14	
15	template <typename T>
16	class KernelForeachTanh {
17	public:
18	    __aicore__ inline KernelForeachTanh() {}
19	
20	    __aicore__ inline void Init(GM_ADDR x, GM_ADDR y,
21	                                int64_t formerNum, int64_t formerLength,
22	                                int64_t tailLength, int64_t tileLength)
23	    {
24	        int64_t blockIdx = AscendC::GetBlockIdx();
25	
26	        if (blockIdx < formerNum) {
27	            this->blockLength = formerLength;
28	            int64_t offset = formerLength * blockIdx;
29	            xGm.SetGlobalBuffer((__gm__ T *)x + offset, formerLength);
30	            yGm.SetGlobalBuffer((__gm__ T *)y + offset, formerLength);
31	        } else {
32	            this->blockLength = tailLength;
33	            int64_t tailIdx = blockIdx - formerNum;
34	            int64_t offset = formerLength * formerNum + tailLength * tailIdx;
35	            xGm.SetGlobalBuffer((__gm__ T *)x + offset, tailLength);
36	            yGm.SetGlobalBuffer((__gm__ T *)y + offset, tailLength);
37	        }
38	
39	        this->tileLength = tileLength;
40	
41	        pipe.InitBuffer(inQueueX, BUFFER_NUM, tileLength * sizeof(T));
42	        pipe.InitBuffer(outQueueY, BUFFER_NUM, tileLength * sizeof(T));
43	
44	        if constexpr (sizeof(T) != sizeof(float)) {
45	            pipe.InitBuffer(tmpBufX, tileLength * sizeof(float));
46	            pipe.InitBuffer(tmpBufY, tileLength * sizeof(float));
47	        }
48	    }
49	
50	    __aicore__ inline void Process()
51	    {
52	        int64_t tileNum = (this->blockLength + this->tileLength - 1) / this->tileLength;
53	        int64_t tailTileLength = this->blockLength - (tileNum - 1) * this->tileLength;
54	
55	        int64_t alignNum = 32 / static_cast<int64_t>(sizeof(T));
56	        int64_t alignedTailLen = ((tailTileLength + alignNum - 1) / alignNum) * alignNum;
57	
58	        for (int64_t i = 0; i < tileNum - 1; ++i) {
59	            CopyIn(i, this->tileLength);
60	            Compute(i, this->tileLength);
61	            CopyOut(i, this->tileLength);
62	        }
63	        if (tileNum > 0) {
64	            CopyIn(tileNum - 1, alignedTailLen);
65	            Compute(tileNum - 1, alignedTailLen);
66	            CopyOut(tileNum - 1, alignedTailLen);
67	        }
68	    }
69	
70	private:
71	    __aicore__ inline void CopyIn(int64_t progress, int64_t curTileLength)
72	    {
73	        AscendC::LocalTensor<T> xLocal = inQueueX.AllocTensor<T>();
74	        AscendC::DataCopyExtParams copyParams{
75	            1,
76	            static_cast<uint32_t>(curTileLength * sizeof(T)),
77	            0, 0, 0
78	        };
79	        AscendC::DataCopyPad(xLocal, xGm[progress * this->tileLength], copyParams);
80	        inQueueX.EnQue(xLocal);
81	    }
82	
83	    __aicore__ inline void Compute(int64_t progress, int64_t curTileLength)
84	    {
85	        AscendC::LocalTensor<T> xLocal = inQueueX.DeQue<T>();
86	        AscendC::LocalTensor<T> yLocal = outQueueY.AllocTensor<T>();
87	
88	        if constexpr (sizeof(T) == sizeof(float)) {
89	            AscendC::Tanh(yLocal, xLocal, curTileLength);
90	        } else {
91	            AscendC::LocalTensor<float> xFp32 = tmpBufX.Get<float>();
92	            AscendC::LocalTensor<float> yFp32 = tmpBufY.Get<float>();
93	
94	            AscendC::Cast(xFp32, xLocal, AscendC::RoundMode::CAST_NONE, curTileLength);
95	            AscendC::Tanh(yFp32, xFp32, curTileLength);
96	            AscendC::Cast(yLocal, yFp32, AscendC::RoundMode::CAST_ROUND, curTileLength);
97	        }
98	
99	        outQueueY.EnQue<T>(yLocal);
100	        inQueueX.FreeTensor(xLocal);
101	    }
102	
103	    __aicore__ inline void CopyOut(int64_t progress, int64_t curTileLength)
104	    {
105	        AscendC::LocalTensor<T> yLocal = outQueueY.DeQue<T>();
106	        AscendC::DataCopyExtParams copyParams{
107	            1,
108	            static_cast<uint32_t>(curTileLength * sizeof(T)),
109	            0, 0, 0
110	        };
111	        AscendC::DataCopyPad(yGm[progress * this->tileLength], yLocal, copyParams);
112	        outQueueY.FreeTensor(yLocal);
113	    }
114	
115	private:
116	    AscendC::TPipe pipe;
117	    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> inQueueX;
118	    AscendC::TQue<AscendC::TPosition::VECOUT, BUFFER_NUM> outQueueY;
119	    AscendC::TBuf<AscendC::TPosition::VECCALC> tmpBufX;
120	    AscendC::TBuf<AscendC::TPosition::VECCALC> tmpBufY;
121	    AscendC::GlobalTensor<T> xGm;
122	    AscendC::GlobalTensor<T> yGm;
123	    int64_t blockLength;
124	    int64_t tileLength;
125	};
126	
127	extern "C" __global__ __aicore__ void foreach_tanh(GM_ADDR x, GM_ADDR y,
128	                                                     int64_t formerNum, int64_t formerLength,
129	                                                     int64_t tailLength, int64_t tileLength,
130	                                                     int64_t dtypeSize)
131	{
132	    if (dtypeSize == 2) {
133	        KernelForeachTanh<half> op;
134	        op.Init(x, y, formerNum, formerLength, tailLength, tileLength);
135	        op.Process();
136	    } else {
137	        KernelForeachTanh<float> op;
138	        op.Init(x, y, formerNum, formerLength, tailLength, tileLength);
139	        op.Process();
140	    }
141	}
