11	#include "kernel_operator.h"
12	
13	constexpr int32_t BUFFER_NUM = 2;
14	
15	template <typename T>
16	class KernelForeachSinh {
17	public:
18	    __aicore__ inline KernelForeachSinh() {}
19	
20	    __aicore__ inline void Init(GM_ADDR x, GM_ADDR y,
21	                                int64_t formerNum, int64_t formerLength,
22	                                int64_t tailLength, int64_t tileLength)
23	    {
24	        int64_t blockIdx = AscendC::GetBlockIdx();
25	
26	        if (blockIdx < formerNum) {
27	            this->blockLength = formerLength;
28	            int64_t offset = formerLength * blockIdx;
29	            xGm.SetGlobalBuffer((__gm__ T *)x + offset, formerLength);
30	            yGm.SetGlobalBuffer((__gm__ T *)y + offset, formerLength);
31	        } else {
32	            this->blockLength = tailLength;
33	            int64_t tailIdx = blockIdx - formerNum;
34	            int64_t offset = formerLength * formerNum + tailLength * tailIdx;
35	            xGm.SetGlobalBuffer((__gm__ T *)x + offset, tailLength);
36	            yGm.SetGlobalBuffer((__gm__ T *)y + offset, tailLength);
37	        }
38	
39	        this->tileLength = tileLength;
40	
41	        pipe.InitBuffer(inQueueX, BUFFER_NUM, tileLength * sizeof(T));
42	        pipe.InitBuffer(outQueueY, BUFFER_NUM, tileLength * sizeof(T));
43	
44	        // FP16/BF16 need FP32 temp buffers for precision upcast
45	        if constexpr (sizeof(T) != sizeof(float)) {
46	            pipe.InitBuffer(tmpBufX, tileLength * sizeof(float));
47	            pipe.InitBuffer(tmpBufY, tileLength * sizeof(float));
48	        }
49	    }
50	
51	    __aicore__ inline void Process()
52	    {
53	        int64_t tileNum = (this->blockLength + this->tileLength - 1) / this->tileLength;
54	        int64_t tailTileLength = this->blockLength - (tileNum - 1) * this->tileLength;
55	
56	        int64_t alignNum = 32 / static_cast<int64_t>(sizeof(T));
57	        int64_t alignedTailLen = ((tailTileLength + alignNum - 1) / alignNum) * alignNum;
58	
59	        for (int64_t i = 0; i < tileNum - 1; ++i) {
60	            CopyIn(i, this->tileLength);
61	            Compute(i, this->tileLength);
62	            CopyOut(i, this->tileLength);
63	        }
64	        if (tileNum > 0) {
65	            CopyIn(tileNum - 1, alignedTailLen);
66	            Compute(tileNum - 1, alignedTailLen);
67	            CopyOut(tileNum - 1, alignedTailLen);
68	        }
69	    }
70	
71	private:
72	    __aicore__ inline void CopyIn(int64_t progress, int64_t curTileLength)
73	    {
74	        AscendC::LocalTensor<T> xLocal = inQueueX.AllocTensor<T>();
75	        AscendC::DataCopyExtParams copyParams{1, static_cast<uint32_t>(curTileLength * sizeof(T)), 0, 0, 0};
76	        AscendC::DataCopyPad(xLocal, xGm[progress * this->tileLength], copyParams);
77	        inQueueX.EnQue(xLocal);
78	    }
79	
80	    __aicore__ inline void Compute(int64_t progress, int64_t curTileLength)
81	    {
82	        AscendC::LocalTensor<T> xLocal = inQueueX.DeQue<T>();
83	        AscendC::LocalTensor<T> yLocal = outQueueY.AllocTensor<T>();
84	
85	        if constexpr (sizeof(T) == sizeof(float)) {
86	            // float32: direct computation
87	            AscendC::Sinh(yLocal, xLocal, curTileLength);
88	        } else {
89	            // fp16/bf16: Cast up to fp32 -> compute -> Cast down
90	            AscendC::LocalTensor<float> xLocalFp32 = tmpBufX.Get<float>();
91	            AscendC::LocalTensor<float> yLocalFp32 = tmpBufY.Get<float>();
92	
93	            AscendC::Cast(xLocalFp32, xLocal, AscendC::RoundMode::CAST_NONE, curTileLength);
94	            AscendC::Sinh(yLocalFp32, xLocalFp32, curTileLength);
95	            AscendC::Cast(yLocal, yLocalFp32, AscendC::RoundMode::CAST_ROUND, curTileLength);
96	        }
97	
98	        outQueueY.EnQue<T>(yLocal);
99	        inQueueX.FreeTensor(xLocal);
100	    }
101	
102	    __aicore__ inline void CopyOut(int64_t progress, int64_t curTileLength)
103	    {
104	        AscendC::LocalTensor<T> yLocal = outQueueY.DeQue<T>();
105	        AscendC::DataCopyExtParams copyParams{1, static_cast<uint32_t>(curTileLength * sizeof(T)), 0, 0, 0};
106	        AscendC::DataCopyPad(yGm[progress * this->tileLength], yLocal, copyParams);
107	        outQueueY.FreeTensor(yLocal);
108	    }
109	
110	private:
111	    AscendC::TPipe pipe;
112	    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> inQueueX;
113	    AscendC::TQue<AscendC::TPosition::VECOUT, BUFFER_NUM> outQueueY;
114	    AscendC::TBuf<AscendC::TPosition::VECCALC> tmpBufX;
115	    AscendC::TBuf<AscendC::TPosition::VECCALC> tmpBufY;
116	    AscendC::GlobalTensor<T> xGm;
117	    AscendC::GlobalTensor<T> yGm;
118	    int64_t blockLength;
119	    int64_t tileLength;
120	};
121	
122	extern "C" __global__ __aicore__ void ForeachSinh(GM_ADDR x, GM_ADDR y,
